/**
 * Compiles the native runtime (native/runtime/*.c) into a flat,
 * position-independent blob of x86-64 machine code and writes it to
 * src/native/runtime.generated.ts, together with the offset of every
 * exported `rt_*` function.
 *
 * Only maintainers need to run this (it requires gcc); the generated file is
 * committed, so building native executables works anywhere, even in a browser.
 *
 *   npm run build:runtime
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const src = join(root, "native/runtime");
const work = mkdtempSync(join(tmpdir(), "tsrust-runtime-"));
const flags = [
  "-O2", "-std=gnu11", "-ffreestanding", "-fno-builtin", "-nostdlib",
  "-fPIC", "-fvisibility=hidden", // position-independent, no GOT
  "-fno-stack-protector", "-fno-asynchronous-unwind-tables", "-fno-unwind-tables",
  "-mno-red-zone", "-fcf-protection=none", "-msse4.1",
  "-Wall", "-Wextra", "-Wno-unused-parameter", "-Werror",
];

const objects: string[] = [];
for (const file of readdirSync(src).filter((f) => f.endsWith(".c")).sort()) {
  const obj = join(work, file.replace(/\.c$/, ".o"));
  execFileSync("gcc", [...flags, "-c", join(src, file), "-o", obj], { stdio: "inherit" });
  objects.push(obj);
}
const elf = join(work, "runtime.elf");
execFileSync("gcc", ["-nostdlib", "-static", "-Wl,-T," + join(src, "runtime.ld"), "-Wl,--build-id=none", "-Wl,-z,norelro", "-o", elf, ...objects], { stdio: "inherit" });

// The blob must be relocatable by simply copying it anywhere: no relocations allowed.
const relocs = execFileSync("readelf", ["-rW", elf], { encoding: "utf8" });
if (!/no relocations/.test(relocs)) throw new Error(`runtime has relocations:\n${relocs}`);

// A GOT (global offset table) would hold absolute addresses fixed at link time.
const sections = execFileSync("readelf", ["-SW", elf], { encoding: "utf8" });
const objects0 = objects.map((o) => execFileSync("readelf", ["-rW", o], { encoding: "utf8" })).join("\n");
if (/GOTPCREL|GOTPC/.test(objects0) || /\.got/.test(sections)) throw new Error("runtime code uses the GOT; keep all symbols hidden");

const symbols: Record<string, number> = {};
for (const line of execFileSync("nm", ["--defined-only", elf], { encoding: "utf8" }).split("\n")) {
  const m = /^([0-9a-f]+) [TtDdBb] (rt_\w+)$/.exec(line.trim());
  if (m) symbols[m[2]] = parseInt(m[1], 16);
}
const dataOffset = parseInt(/\.data\s+PROGBITS\s+([0-9a-f]+)/.exec(execFileSync("readelf", ["-SW", elf], { encoding: "utf8" }))![1], 16);
const bin = join(work, "runtime.bin");
execFileSync("objcopy", ["-O", "binary", elf, bin]);
const bytes = readFileSync(bin);

writeFileSync(
  join(root, "src/native/runtime.generated.ts"),
  `/**
 * The TSRust native runtime as x86-64 machine code.
 * GENERATED by scripts/build-runtime.ts from native/runtime/*.c. Do not edit.
 */
export const RUNTIME = {
  /** Offset of the read-write data part (page aligned); everything before it is code and constants. */
  dataOffset: ${dataOffset},
  size: ${bytes.length},
  symbols: ${JSON.stringify(symbols)} as Record<string, number>,
  base64: ${JSON.stringify(bytes.toString("base64"))},
};
`,
);
console.log(`runtime: ${bytes.length} bytes (${dataOffset} code), ${Object.keys(symbols).length} symbols`);
